def configure_sources(apps, schema_editor):
    Technology = apps.get_model("watch", "Technology")
    for technology in Technology.objects.filter(slug__in=SOURCES):
        technology.advisory_sources = SOURCES[technology.slug]
        technology.save(update_fields=["advisory_sources"])
        # Un CVE reste à l'avis qui l'a enregistré en premier : les avis GHSA déjà
        # collectés laissent la place à ceux, plus complets, de la source officielle.
        technology.advisories.all().delete()


